 static SolidColorBrush MonitorBrush(string color){var brush=new SolidColorBrush((Color)ColorConverter.ConvertFromString(color));brush.Freeze();return brush;}
 void CommitMonitorColor(bool background){if(liveChanging)return;var field=background?liveBackgroundHex:liveForegroundHex;if(field==null)return;string hex=MonitorOptions.ColorHex(field.Text,"");if(hex.Length==0){field.ToolTip=T("Use six hexadecimal digits, for example #202020.","输入六位十六进制颜色，例如 #202020。");return;}ChangeMonitor(o=>{o.TaskbarColorMode=1;if(background)o.TaskbarBackground=hex;else o.TaskbarForeground=hex;});}
 void PickMonitorColor(bool background){var settings=MonitorOptions.Load(Store.Root);string hex=background?settings.TaskbarBackground:settings.TaskbarForeground;var color=(Color)ColorConverter.ConvertFromString(hex);IntPtr custom=Marshal.AllocHGlobal(64);try{for(int i=0;i<16;i++)Marshal.WriteInt32(custom,i*4,0x00FFFFFF);var dialog=new ChooseColorData{Size=(uint)Marshal.SizeOf(typeof(ChooseColorData)),Owner=new WindowInteropHelper(this).Handle,Result=(uint)(color.R|(color.G<<8)|(color.B<<16)),Custom=custom,Flags=0x00000003};if(ChooseMonitorColor(ref dialog)){string result="#"+((byte)dialog.Result).ToString("X2")+((byte)(dialog.Result>>8)).ToString("X2")+((byte)(dialog.Result>>16)).ToString("X2");ChangeMonitor(o=>{o.TaskbarColorMode=1;if(background)o.TaskbarBackground=result;else o.TaskbarForeground=result;});}}finally{Marshal.FreeHGlobal(custom);}}
 void AddMonitorColorControls(MonitorOptions options){
  Heading("Taskbar colors","任务栏配色");var modeRow=new WrapPanel{Margin=new Thickness(0,0,0,8)};liveColorMode=new ComboBox{ItemsSource=zh?new[]{"跟随任务栏（自动）","自定义颜色"}:new[]{"Match taskbar (automatic)","Custom colors"},SelectedIndex=options.TaskbarColorMode,MinWidth=245,Margin=new Thickness(0,0,12,8)};liveColorMode.SelectionChanged+=(s,e)=>{if(!liveChanging&&liveColorMode.SelectedIndex>=0)ChangeMonitor(o=>o.TaskbarColorMode=liveColorMode.SelectedIndex);};modeRow.Children.Add(liveColorMode);liveCopyColors=new Button{Content=T("Customize current colors","基于当前颜色自定义"),Padding=new Thickness(12,6,12,6),Margin=new Thickness(0,0,0,8)};liveCopyColors.Click+=(s,e)=>{var bg=((SolidColorBrush)liveColorPreview.Background).Color;var fg=((SolidColorBrush)livePreviewText.Foreground).Color;ChangeMonitor(o=>{o.TaskbarColorMode=1;o.TaskbarBackground="#"+bg.R.ToString("X2")+bg.G.ToString("X2")+bg.B.ToString("X2");o.TaskbarForeground="#"+fg.R.ToString("X2")+fg.G.ToString("X2")+fg.B.ToString("X2");});};modeRow.Children.Add(liveCopyColors);page.Children.Add(modeRow);
  liveCustomColors=new WrapPanel{Margin=new Thickness(0,0,0,8)};
