 void SyncMonitorColorControls(MonitorOptions options){if(liveColorMode==null)return;bool prior=liveChanging;liveChanging=true;try{liveColorMode.SelectedIndex=options.TaskbarColorMode;liveCustomColors.IsEnabled=options.TaskbarColorMode==1;if(!liveBackgroundHex.IsKeyboardFocusWithin)liveBackgroundHex.Text=options.TaskbarBackground;if(!liveForegroundHex.IsKeyboardFocusWithin)liveForegroundHex.Text=options.TaskbarForeground;string background=options.TaskbarBackground,foreground=options.TaskbarForeground;if(options.TaskbarColorMode==0){if(liveSnapshot!=null&&liveSnapshot.TaskbarColorMode==0&&!String.IsNullOrEmpty(liveSnapshot.TaskbarBackground)){background=liveSnapshot.TaskbarBackground;foreground=liveSnapshot.TaskbarForeground;}else{background=dark?"#101010":"#F3F3F3";foreground=dark?"#F5F5F5":"#141414";}}var existing=liveColorPreview.Background as SolidColorBrush;if(existing==null||existing.Color!=(Color)ColorConverter.ConvertFromString(background))liveColorPreview.Background=MonitorBrush(background);var ink=livePreviewText.Foreground as SolidColorBrush;if(ink==null||ink.Color!=(Color)ColorConverter.ConvertFromString(foreground))livePreviewText.Foreground=MonitorBrush(foreground);liveBackgroundPick.Background=MonitorBrush(options.TaskbarBackground);liveBackgroundPick.Foreground=MonitorBrush(options.TaskbarForeground);liveForegroundPick.Background=MonitorBrush(options.TaskbarBackground);liveForegroundPick.Foreground=MonitorBrush(options.TaskbarForeground);}finally{liveChanging=prior;}}
